def section(name):
    if name not in TYPES: return ''
    cards=''
    for title,svg,look,pros,cons,use in TYPES[name]:
        cards+=f'''<div class="tcard"><div class="tart">{svg}</div><h3>{title}</h3><p class="tlook">{look}</p><ul class="tpc">{''.join(f'<li class="p">✓ {p}</li>' for p in pros)}{''.join(f'<li class="c">✗ {c}</li>' for c in cons)}</ul><p class="tuse"><b>Use for:</b> {use}</p></div>'''
    word={'resistor':'resistors','capacitor':'capacitors','diode':'diodes','led':'LEDs','transistor':'transistors','inductor':'inductors','relay':'relays','motion':'buzzers, speakers and motors'}[name]
    return f'''<section>
  <h2><span class="num">0</span>The types of {word} you'll meet</h2>
  <p>Same job, different builds. Here's how to <b>recognise</b> each one, and its pros and cons.</p>
  <div class="tcards">{cards}</div>
</section>
'''
